<?php require '_auth.php';$adminTitle='Customers';$users=$pdo->query("SELECT u.*,COUNT(o.id) orders_count,COALESCE(SUM(o.total),0) spent FROM users u LEFT JOIN orders o ON o.user_id=u.id GROUP BY u.id ORDER BY u.id DESC")->fetchAll();include '_header.php';?><section class="panel"><div class="panel-head"><h2>Registered customers</h2></div><table class="table"><tr><th>ID</th><th>Name</th><th>Email</th><th>Orders</th><th>Total spent</th><th>Joined</th></tr><?php foreach($users as $u):?><tr><td>#<?=$u['id']?></td><td><?=e($u['name'])?></td><td><?=e($u['email'])?></td><td><?=$u['orders_count']?></td><td>LKR <?=number_format($u['spent'],2)?></td><td><?=e($u['created_at'])?></td></tr><?php endforeach;?></table></section><?php include '_footer.php';?>
